content:
@import "tailwindcss";
@theme {
  --color-brand: #204f5f;
  --color-lime: #b1ca00;
  --font-sans: "Manrope Variable", sans-serif;
}
.admin-job-fields { display: grid; gap: 16px; border: 0; padding: 0; min-width: 0; }
:root {
  /* Paleta de districo.com.uy (Elementor post-11.css y post-53.css) */
  --ink: #204f5f;
  --ink-deep: #163d4a;
  --lime: #b1ca00;
  --lime-text: #5f7300;
  --lime-soft: color-mix(in srgb, var(--lime) 18%, white);
  --text: #636466;
  --muted: #636466;
  --line: #dcdcdc;
  --paper: #efefef;
  --on-ink: #ffffff;
  --on-ink-muted: #c9d6da;
  --on-ink-line: rgb(255 255 255 / 0.14);
  --radius: 18px;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
  color: var(--ink);
  background: white;
  font-family: "Manrope Variable", sans-serif;
  font-size: 14px;
  line-height: 1.65;
}
a {
  color: inherit;
  text-decoration: none;
}
button,
input,
select,
textarea {
  font: inherit;
}
button,
a,
input,
select,
textarea {
  -webkit-tap-highlight-color: transparent;
}
button {
  cursor: pointer;
}
button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
input,
select,
textarea {
  max-width: 100%;
}
img {
  max-width: 100%;
  display: block;
}
h1,
h2,
h3,
p {
  margin: 0;
}
h1,
h2,
h3 {
  line-height: 1.2;
  letter-spacing: -0.045em;
}
h1 {
  font-size: clamp(30px, 4vw, 48px);
  font-weight: 650;
}
h2 {
  font-size: clamp(24px, 2.6vw, 34px);
  font-weight: 650;
}
h3 {
  font-size: 18px;
  font-weight: 650;
}
p + p {
  margin-top: 14px;
}
a:hover {
  color: var(--lime-text);
}
button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--lime-text);
  outline-offset: 4px;
}
::selection {
  background: var(--lime-soft);
}
svg {
  flex-shrink: 0;
}

.admin-command-trigger { display: flex; align-items: center; gap: 10px; width: 100%; padding: 12px; border: 1px solid var(--line); border-radius: 4px; background: white; color: var(--ink); font-size: 13px; text-align: left; }
.admin-sidebar[data-collapsed="true"] .admin-command-trigger { justify-content: center; padding: 12px 0; }
.admin-sidebar[data-collapsed="true"] .admin-command-trigger span { display: none; }
.modal.admin-command-dialog { width: min(640px, calc(100vw - 24px)); }
.admin-command-results { display: grid; gap: 4px; margin-top: 12px; max-height: 52svh; overflow-y: auto; }
.admin-command-result { display: grid; grid-template-columns: 20px minmax(0, 1fr) 16px; align-items: center; gap: 12px; width: 100%; padding: 12px; border: 1px solid transparent; border-radius: 4px; background: white; color: var(--ink); text-align: left; }
.admin-command-result[aria-selected="true"] { border-color: var(--line); background: var(--paper); }
.admin-command-result strong, .admin-command-result small { display: block; overflow-wrap: anywhere; }
.admin-command-result small { margin-top: 3px; color: var(--muted); }
.admin-bulk-toolbar { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; padding: 12px 0; border-block: 1px solid var(--line); margin-block: 16px; font-size: 13px; }
.admin-selection-cell { width: 44px; text-align: center; }
.admin-selection-cell input { width: 17px; height: 17px; accent-color: var(--ink); cursor: pointer; }
.admin-history-actions { margin-block: 12px; justify-content: flex-end; }
.modal.admin-bulk-dialog { width: min(880px, calc(100vw - 24px)); }
.admin-bulk-fields { display: grid; gap: 16px; border: 0; padding: 0; min-width: 0; }
.admin-bulk-names { display: flex; flex-wrap: wrap; gap: 6px 16px; max-height: 120px; overflow-y: auto; font-size: 13px; }
.admin-bulk-preview { max-height: 42svh; overflow: auto; }
.admin-bulk-preview td { overflow-wrap: anywhere; min-width: 110px; }
.admin-bulk-preview th:first-child { width: 55%; }
.admin-bulk-history { padding-block: 14px; border-bottom: 1px solid var(--line); }
.admin-bulk-history summary { cursor: pointer; font-size: 13px; }
.admin-bulk-history p { margin-block: 12px; overflow-wrap: anywhere; }
.admin-seller-options { display: grid; gap: 8px; max-height: 200px; overflow-y: auto; }
.order-return-table input[type="number"] { width: 90px; min-width: 70px; }
.order-return-table .check-field { min-width: 190px; align-items: flex-start; }
.order-return-table .check-field small { display: block; color: var(--muted); }
.order-return-history details { border-bottom: 1px solid var(--line); padding-block: 14px; }
.order-return-history summary { cursor: pointer; font-size: 13px; }
.order-return-history p { margin-block: 12px; overflow-wrap: anywhere; }
.order-return-confirmation { border-block: 1px solid var(--line); padding-block: 16px; }
@media (max-width: 600px) {
  .admin-bulk-toolbar .actions { width: 100%; }
  .admin-command-trigger { width: auto; }
}
.container {
  width: min(1280px, calc(100% - 80px));
  margin-inline: auto;
}
.home-container {
  max-width: none;
  padding-top: clamp(16px, 2vw, 24px);
}
.section {
  padding-block: 64px;
}
.muted {
  color: var(--muted);
}
.eyebrow {
  font-size: 15px;
  font-weight: 750;
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}
.row,
.actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.between {
  justify-content: space-between;
}
.actions {
  margin-top: 24px;
}
.stack {
  display: grid;
  gap: 20px;
}
.button {
  min-height: 46px;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 20px;
  border: 1px solid transparent;
  border-radius: 7px;
  background: var(--ink);
  color: white;
  padding: 12px 22px;
  font-size: 13px;
  font-weight: 650;
  line-height: 1.4;
}
.button:hover {
  background: var(--ink-deep);
  color: white;
  transform: translateY(-1px);
}
.button.lime {
  background: var(--lime);
  color: var(--ink);
}
.button.secondary {
  background: transparent;
  border-color: var(--line);
  color: var(--ink);
}
.button.secondary:hover {
  background: var(--paper);
}
.button.small {
  padding: 8px 14px;
  min-height: 38px;
}
.button.danger {
  background: #9a3535;
}
.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  background: transparent;
  border: 0;
  border-radius: 6px;
}
.icon-button:hover {
  background: var(--paper);
}
.text-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 650;
  font-size: 13px;
}
.skip-link {
  position: fixed;
  left: 20px;
  top: -100px;
  background: var(--ink);
  color: white;
  padding: 12px;
  z-index: 100;
}
.skip-link:focus {
  top: 10px;
}
.demo-strip {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 24px;
  background: var(--lime-soft);
  color: var(--ink);
  padding: 5px 16px;
  font-size: 10px;
  letter-spacing: 0.02em;
}
.demo-strip button {
  text-decoration: underline;
  min-height: 28px;
  border: 0;
  background: transparent;
}
.dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--lime);
  margin-right: 6px;
}
.topbar {
  background: var(--ink-deep);
  color: var(--on-ink-muted);
  font-size: 10px;
  padding: 7px 0;
  letter-spacing: 0.04em;
}
.topbar .container {
  display: flex;
  justify-content: space-between;
}
.whatsapp-fab {
  position: fixed;
  right: 16px;
  bottom: calc(16px + env(safe-area-inset-bottom));
  z-index: 60;
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  color: var(--ink);
  background: var(--lime);
  box-shadow: 0 6px 20px #1234;
  transition: transform 0.2s ease;
}
/* Está dentro del footer: evita que footer a:hover pinte el logo de lima. */
.whatsapp-fab:hover {
  color: var(--ink);
  transform: translateY(-2px);
}
.whatsapp-fab:focus-visible {
  outline: 3px solid var(--ink);
  outline-offset: 3px;
}
@media (min-width: 768px) {
  .whatsapp-fab {
    right: 28px;
    bottom: 28px;
  }
}
.topbar-links {
  display: flex;
  gap: 14px;
  align-items: center;
}
.topbar a {
  display: flex;
  gap: 8px;
  align-items: center;
}
.header {
  background: var(--ink);
  color: var(--on-ink);
  position: relative;
  z-index: 10;
}
.header-main {
  display: flex;
  align-items: center;
  gap: 50px;
  min-height: 96px;
}
.logo {
  flex-shrink: 0;
}
.logo img {
  width: 179px;
  height: auto;
}
.search {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  background: white;
  color: var(--ink);
  border: 0;
  border-radius: 7px;
  padding: 9px 13px;
  flex: 1;
  margin-inline: 20px;
  max-width: 580px;
}
.search-panel {
  position: absolute;
  z-index: 60;
  top: calc(100% + 8px);
  inset-inline: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: white;
  color: var(--ink);
  box-shadow: 0 18px 40px rgb(22 61 74 / 0.18);
  animation: search-panel-in 180ms ease-out;
}
.search-panel[hidden] {
  display: none;
}
.search-panel ul {
  margin: 0;
  padding: 6px;
  list-style: none;
}
.search-panel li a {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px;
  border-radius: 8px;
  color: inherit;
}
.search-panel li a:hover,
.search-panel li a:focus-visible {
  background: var(--lime-soft);
  outline: none;
}
.search-panel li img {
  flex: none;
  width: 44px;
  height: 44px;
  object-fit: contain;
  border-radius: 6px;
  background: var(--paper);
}
.search-panel li span {
  display: grid;
  flex: 1;
  min-width: 0;
}
.search-panel strong {
  overflow: hidden;
  font-size: 13px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.search-panel small {
  color: var(--muted);
  font-size: 11px;
}
.search-panel-price {
  flex: none;
  margin-left: auto;
  color: var(--ink);
  font-size: 13px;
  font-style: normal;
  font-weight: 800;
  white-space: nowrap;
}
.search-panel-price.is-hidden {
  max-width: 110px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
  white-space: normal;
  text-align: right;
}
.search-panel-note {
  margin: 0;
  padding: 16px;
  color: var(--muted);
  font-size: 13px;
}
.search-panel-all {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-top: 1px solid var(--line);
  color: var(--ink);
  font-size: 12px;
  font-weight: 800;
}
.search-panel-all:hover,
.search-panel-all:focus-visible {
  background: var(--paper);
  outline: none;
}
@keyframes search-panel-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .search-panel {
    animation: none;
  }
}
.search:focus-within {
  outline: 3px solid var(--lime);
  outline-offset: 2px;
}
.search input {
  background: transparent;
  border: 0;
  outline: none;
  min-width: 0;
  width: 100%;
  font-size: 12px;
}
.search button {
  background: transparent;
  border: 0;
  display: flex;
  width: 30px;
  height: 30px;
  align-items: center;
  justify-content: center;
}
.header-actions {
  display: flex;
  gap: 28px;
  align-items: center;
  margin-left: auto;
}
.account-link {
  display: flex;
  gap: 12px;
  align-items: center;
  font-size: 12px;
  font-weight: 650;
  white-space: nowrap;
}
.account-link small {
  display: block;
  color: var(--on-ink-muted);
  font-size: 10px;
  font-weight: 400;
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cart-link {
  position: relative;
}
.cart-count {
  position: absolute;
  right: 0;
  top: 0;
  background: var(--lime);
  border-radius: 50%;
  font-size: 9px;
  width: 16px;
  height: 16px;
  color: var(--ink);
  text-align: center;
}
.navline {
  border-top: 1px solid var(--on-ink-line);
}
.header a:hover,
.topbar a:hover {
  color: var(--lime);
}
.header :focus-visible,
.topbar :focus-visible {
  outline-color: var(--lime);
}
.header .icon-button {
  color: inherit;
}
.header .icon-button:hover {
  background: var(--on-ink-line);
}
.navline nav {
  display: flex;
  gap: 38px;
  align-items: center;
  height: 48px;
  font-size: 12px;
  font-weight: 600;
}
.navline .active {
  color: var(--lime);
}
.navline > nav { position: relative; }
.catalog-nav-entry { display: flex; align-items: center; gap: 2px; }
.catalog-nav-entry > a { display: inline-flex; align-items: center; min-height: 48px; }
.catalog-nav-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 40px;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
}
.catalog-nav-toggle:hover, .catalog-nav-toggle[aria-expanded="true"] { color: var(--lime); background: var(--on-ink-line); }
.catalog-nav-toggle svg { transition: transform 150ms ease; }
.catalog-nav-toggle[aria-expanded="true"] svg { transform: rotate(180deg); }
.catalog-menu {
  position: absolute;
  inset-inline: 0;
  top: 100%;
  z-index: 50;
  max-height: min(620px, calc(100dvh - 205px));
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 20px 24px 24px;
  border: 1px solid var(--line);
  border-top: 3px solid var(--lime);
  border-radius: 0 0 8px 8px;
  background: white;
  color: var(--ink);
  box-shadow: 0 16px 32px rgb(22 61 74 / 0.16);
  font-size: 13px;
  font-weight: 400;
  line-height: 1.5;
  letter-spacing: 0;
}
.catalog-menu[hidden] { display: none; }
.catalog-menu-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding-bottom: 16px; margin-bottom: 20px; border-bottom: 1px solid var(--line); }
.catalog-menu-head p { display: flex; align-items: baseline; flex-wrap: wrap; gap: 4px 12px; margin: 0; }
.catalog-menu-head strong { font-size: 16px; font-weight: 750; }
.catalog-menu-head p span { color: var(--muted); font-size: 12px; }
.catalog-menu-head > a { display: inline-flex; align-items: center; gap: 8px; color: var(--lime-text); font-weight: 750; }
/* Tarjetas por especie (opción B elegida el 12/10/2026). */
.catalog-menu-grid { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 14px; }
.catalog-menu-column { min-width: 0; }
.catalog-menu .catalog-menu-root { display: grid; justify-items: center; align-content: center; gap: 6px; min-height: 92px; padding: 14px 10px; border-radius: 14px; background: var(--lime-soft); color: var(--ink); font-size: 14px; font-weight: 750; line-height: 1.2; text-align: center; overflow-wrap: anywhere; transition: background-color .18s ease, color .18s ease, transform .18s ease; }
.catalog-menu .catalog-menu-root svg { color: var(--lime-text); transition: color .18s ease; }
.catalog-menu [data-featured] .catalog-menu-root { background: var(--ink); color: white; }
.catalog-menu [data-featured] .catalog-menu-root svg, .catalog-menu .catalog-menu-root:hover svg { color: var(--lime); }
.catalog-menu .catalog-menu-root:hover { transform: translateY(-2px); background: var(--ink-deep); color: white; }
.catalog-menu .catalog-menu-root[aria-current="page"] { box-shadow: 0 0 0 2px var(--lime); }
.catalog-menu-column > ul { margin-top: 8px; }
.catalog-nav:not(.catalog-nav-mobile) .catalog-menu-column li > ul,
.catalog-nav:not(.catalog-nav-mobile) .catalog-menu-extra,
.catalog-nav-mobile .catalog-menu-more { display: none; }
.catalog-menu-more > a { color: var(--lime-text); font-weight: 750; }
.catalog-menu ul { list-style: none; margin: 0; padding: 0; }
.catalog-menu li > a { display: block; padding: 6px 8px; border-radius: 6px; overflow-wrap: anywhere; }
.catalog-menu li + li { margin-top: 2px; }
.catalog-menu li > ul { padding-left: 12px; border-left: 1px solid var(--line); margin: 4px 0 10px; }
.catalog-menu-branch { font-weight: 650; }
.catalog-menu a:hover, .catalog-menu a[aria-current="page"] { color: var(--lime-text); }
.catalog-menu li > a:hover, .catalog-menu li > a:focus-visible { background: var(--lime-soft); }
.catalog-menu a:focus-visible, .catalog-menu button:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }
.catalog-menu-status { display: flex; align-items: center; gap: 16px; padding-block: 16px; }
.catalog-nav-mobile .catalog-nav-entry { justify-content: space-between; }
.mobile-nav .catalog-nav-toggle { flex: none; width: 48px; height: 48px; padding: 0; align-items: center; justify-content: center; background: transparent; }
.mobile-nav .catalog-nav-toggle:hover, .mobile-nav .catalog-nav-toggle[aria-expanded="true"] { color: var(--lime-text); background: var(--lime-soft); }
.catalog-nav-mobile .catalog-menu { position: static; max-height: none; padding: 14px; border-top-width: 1px; border-radius: 4px; box-shadow: none; }
.catalog-nav-mobile .catalog-menu-grid { grid-template-columns: minmax(0, 1fr); gap: 20px; }
.catalog-nav-mobile .catalog-menu-head > strong { display: none; }
.catalog-nav-mobile .catalog-menu-heading { min-height: auto; align-items: center; }
.mobile-nav .catalog-menu a { padding: 8px 6px; min-height: 40px; font-size: 13px; }
.mobile-nav .catalog-menu-root { font-size: 14px; }
.mobile-nav .catalog-menu-head > a { padding: 0; }
@media (min-width: 768px) and (max-width: 1100px) {
  .catalog-menu-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px 32px; }
}
@media (prefers-reduced-motion: reduce) {
  .catalog-nav-toggle svg { transition: none; }
}
.mobile-nav .active {
  color: var(--lime-text);
}
.be-client {
  margin-left: auto;
  display: flex;
  gap: 14px;
  align-items: center;
}
.mobile-menu {
  display: none;
}
.page-heading {
  margin-bottom: 32px;
}
.page-heading .muted {
  margin-top: 14px;
  max-width: 660px;
}
.breadcrumbs {
  font-size: 11px;
  color: var(--muted);
  margin-bottom: 28px;
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}
.hero {
  border-radius: var(--radius);
  background: var(--paper);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 1.12fr;
  min-height: 430px;
  position: relative;
}
.hero-copy {
  padding: 55px 48px;
  position: relative;
  z-index: 1;
}
.hero h1 {
  font-size: clamp(36px, 4.6vw, 60px);
  line-height: 1.09;
  max-width: 520px;
  font-weight: 550;
}
.hero h1 em {
  font-style: normal;
  color: var(--lime-text);
}
.hero-copy > p:not(.eyebrow) {
  color: var(--text);
  max-width: 340px;
  font-size: 13px;
  margin-top: 20px;
}
.hero .actions {
  margin-top: 28px;
}
.hero-visual {
  position: relative;
  overflow: hidden;
  background: var(--paper);
}
.hero-visual picture,
.hero-visual img {
  height: 100%;
  width: 100%;
  object-fit: cover;
}
.hero-caption {
  position: absolute;
  bottom: 18px;
  right: 18px;
  border-radius: 8px;
  background: #fffffff0;
  padding: 13px 18px;
  font-size: 10px;
  box-shadow: 0 3px 30px #1526140c;
}
.hero-caption strong {
  display: block;
  font-size: 13px;
}
.home-carousel-stage {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius);
  aspect-ratio: 39 / 10;
}
.home-carousel-stage .hero {
  min-height: 0;
}
.home-carousel-slide {
  display: block;
  position: relative;
  background: #f4f1ec;
  height: 100%;
}
.home-carousel-slide .hero-visual {
  position: relative;
  height: 100%;
  min-width: 0;
  background: #f4f1ec;
}
.home-carousel-slide .hero-visual picture {
  display: block;
  width: 100%;
  height: 100%;
}
.home-carousel-slide .hero-visual img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
}
.home-carousel-slide .hero-copy {
  position: absolute;
  z-index: 1;
  top: 50%;
  left: 24px;
  transform: translateY(-50%);
