/* Ficha de producto: vitrina, datos y presentaciones, bloque de compra.
   Una columna en móvil, dos desde 900px y tres desde 1200px. */
.detail-page { padding-top: 38px; }
.detail-page .breadcrumbs { margin-bottom: 24px; }
.detail-grid {
  display: grid;
  gap: 28px;
  align-items: start;
}
.detail-gallery, .detail-info, .detail-purchase { min-width: 0; }
@media (min-width: 900px) {
  .detail-grid {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    grid-template-areas: "gallery info" "gallery buy";
    gap: 28px clamp(32px, 4vw, 48px);
  }
  .detail-gallery { grid-area: gallery; }
  .detail-info { grid-area: info; }
  .detail-purchase { grid-area: buy; }
}
@media (min-width: 1200px) {
  .detail-grid {
    grid-template-columns: minmax(0, 5fr) minmax(0, 4fr) 340px;
