}
.detail-brand img { display: block; width: auto; height: 28px; max-width: 140px; object-fit: contain; }
.detail-brand a { color: var(--ink); }
.detail-brand a:hover { text-decoration: underline; text-underline-offset: 3px; }
.detail-edit { margin-left: auto; }
.detail-meta {
