  flex-wrap: wrap;
  gap: 4px 16px;
  color: var(--muted);
  font-size: 13px;
}
.detail-lead {
  margin-top: 16px;
  font-size: 15px;
  line-height: 1.6;
  max-width: 54ch;
}
.detail-availability {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #2f6b3a;
  font-size: 14px;
  font-weight: 750;
}
.detail-availability > span {
  display: inline-flex;
