}
.detail-availability > span.is-unavailable { color: #a33a1f; }
.detail-availability > span.is-unavailable::before { background: #c2502f; }
.detail-pills:empty { display: none; }
.detail-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
}
.detail-assistance { color: var(--muted); font-size: 13px; text-align: center; }
.detail-assistance a { color: var(--ink); font-weight: 750; text-decoration: underline; text-underline-offset: 3px; }
.detail-variants, .detail-benefits { margin-top: 24px; }
.detail-variants > p, .detail-benefits > p {
  margin-bottom: 12px;
  color: var(--ink-deep);
  font-size: 14px;
  font-weight: 800;
}
.detail-variants [role="radiogroup"] {
