}
.detail-variants button[aria-checked="true"] .detail-variant-dot { border-color: var(--ink); }
.detail-variants button[aria-checked="true"] .detail-variant-dot::after {
  content: "";
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--ink);
}
.detail-variant-name {
  display: grid;
  gap: 2px;
  font-size: 15px;
