}
.detail-purchase .detail-buy .actions { display: grid; gap: 10px; }
.detail-purchase .quantity { display: flex; width: 100%; height: 52px; border-width: 1.5px; border-radius: 14px; }
.detail-purchase .quantity button { flex: 0 0 52px; width: 52px; background: #f6f6f4; color: var(--ink-deep); }
.detail-purchase .quantity button:hover:not(:disabled) { background: #ececea; }
.detail-purchase .quantity input { flex: 1; width: auto; min-width: 0; color: var(--ink-deep); font-size: 18px; font-weight: 800; }
.detail-purchase .detail-buy .actions > .button {
  min-height: 54px;
  border-radius: 999px;
  background: var(--lime);
  color: var(--ink-deep);
  font-size: 16px;
  font-weight: 800;
}
.detail-purchase .detail-buy .actions > .button:hover:not(:disabled) { background: #c2d82a; }
.detail-purchase .detail-buy .info-note { margin-top: 10px; }
.detail-details { margin-top: clamp(40px, 6vw, 72px); padding-top: clamp(32px, 4vw, 48px); border-top: 1px solid var(--line); }
.detail-details > h2 {
  margin-bottom: 20px;
  color: var(--ink-deep);
  font-size: clamp(24px, 2.6vw, 28px);
  font-weight: 800;
  letter-spacing: -0.01em;
}
/* Secciones de información (ficha pública y tienda): acordeón en móvil,
   pestañas verticales desde 900px con la misma estructura. */
.product-sections { border-top: 1px solid var(--line); }
.product-section-head { margin: 0; font-size: inherit; }
.product-section-head button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  min-height: 58px;
  padding: 16px 0;
  border: 0;
  border-bottom: 1px solid var(--line);
  background: none;
  color: var(--ink-deep);
  font: inherit;
  font-size: 16px;
  font-weight: 800;
  text-align: left;
  cursor: pointer;
}
.product-section-head svg { flex: none; transition: transform var(--dur-base) var(--ease-out); }
.product-section-head button[aria-expanded="true"] svg { transform: rotate(180deg); }
.product-section-body {
  min-width: 0;
  padding: 16px 0 24px;
  border-bottom: 1px solid var(--line);
  color: var(--text);
  font-size: 15px;
  line-height: 1.7;
}
.product-section-text { max-width: 74ch; white-space: pre-line; }
.product-section-body .tech-acc-body { padding: 0; font-size: 15px; }
@media (min-width: 900px) {
  .product-sections {
    display: grid;
    grid-template-columns: 240px minmax(0, 1fr);
    align-items: start;
    column-gap: clamp(32px, 5vw, 64px);
    border-top: 0;
  }
  .product-section-head { grid-column: 1; }
  .product-section-head button {
    min-height: 50px;
    margin-bottom: 4px;
    padding: 12px 16px;
    border: 0;
    border-radius: 14px;
    color: var(--muted);
  }
  .product-section-head button:hover { background: var(--paper); color: var(--ink-deep); }
  .product-section-head button[aria-expanded="true"] {
    background: #eef2f3;
    color: var(--ink-deep);
    box-shadow: inset 3px 0 0 var(--lime);
  }
  .product-section-head svg { display: none; }
  .product-section-body { grid-column: 2; grid-row: 1 / -1; padding: 0; border: 0; }
}
@media (prefers-reduced-motion: reduce) { .product-section-head svg { transition: none; } }
/* Información técnica en acordeón (vista previa del panel). */
.tech-acc { margin-top: 12px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--paper); interpolate-size: allow-keywords; }
.tech-acc::details-content { block-size: 0; overflow: hidden; transition: block-size var(--dur-base) var(--ease-out), content-visibility var(--dur-base) allow-discrete; }
.tech-acc[open]::details-content { block-size: auto; }
.tech-acc summary { display: flex; justify-content: space-between; gap: 12px; padding: 14px 18px; font-weight: 750; cursor: pointer; list-style: none; user-select: none; }
.tech-acc summary::-webkit-details-marker { display: none; }
.tech-acc summary::after { content: "+"; font-size: 20px; line-height: 1; }
.tech-acc[open] summary::after { content: "−"; }
.tech-acc summary:hover { color: var(--lime-text); }
.tech-acc summary:focus-visible { outline: 2px solid var(--ink); outline-offset: -2px; border-radius: var(--radius); }
.tech-acc-body { padding: 0 18px 18px; overflow-x: auto; color: var(--text); font-size: 14px; }
.tech-acc-body p { margin: 0 0 12px; }
.tech-acc-body table { min-width: max-content; margin-top: 8px; border-collapse: collapse; background: white; }
.tech-acc-body th, .tech-acc-body td { padding: 8px 11px; border: 1px solid var(--line); text-align: left; vertical-align: top; }
.tech-acc-body th { color: var(--ink); font-weight: 750; }
.tech-acc-body thead th { background: var(--paper); white-space: nowrap; }
.tech-acc-body thead th:first-child, .tech-acc-body tbody th:not([colspan]) { position: sticky; left: 0; z-index: 1; background: var(--paper); }
.tech-acc-note { font-size: 12px; opacity: .75; }
@media (prefers-reduced-motion: reduce) { .tech-acc::details-content { transition: none; } }
/* Barra de compra en mobile: entra desde abajo cuando el bloque de compra
   quedó fuera de la vista. */
.detail-buybar {
  position: fixed;
  inset: auto 0 0;
  z-index: 55;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px calc(12px + env(safe-area-inset-bottom));
  background: white;
  border-top: 1px solid var(--line);
  box-shadow: 0 -8px 24px rgb(32 79 95 / 0.1);
  transform: translateY(110%);
  visibility: hidden;
  transition: transform var(--dur-base) ease, visibility 0s linear var(--dur-base);
}
.detail-buybar.is-visible {
  transform: none;
  visibility: visible;
  transition-delay: 0s;
}
.detail-buybar > div {
  display: grid;
  min-width: 0;
}
.detail-buybar small {
  overflow: hidden;
  color: var(--muted);
  font-size: 11px;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.detail-buybar strong {
  color: var(--ink);
  font-size: 17px;
}
.detail-buybar .button {
  flex: 0 0 auto;
}
body:has(.detail-buybar.is-visible) .whatsapp-fab {
  bottom: calc(84px + env(safe-area-inset-bottom));
}
@media (min-width: 900px) {
  .detail-buybar {
    display: none;
  }
}
.detail-specs {
  display: grid;
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}
.detail-specs > div {
  display: grid;
  grid-template-columns: 130px minmax(0, 1fr);
  gap: 16px;
  padding: 12px 16px;
}
.detail-specs > div:nth-child(odd) {
  background: var(--paper);
}
.detail-specs dt {
  font-weight: 700;
  color: var(--ink);
}
.detail-specs a {
  color: var(--ink);
  text-decoration: underline;
}
.detail-related {
  margin-top: 64px;
}
.detail-image {
  /* Vitrina blanca: los JPG con fondo blanco se funden sin teñirse;
     la foto termina justo donde empieza el estante. */
  position: relative;
  isolation: isolate;
  aspect-ratio: 4 / 5;
  overflow: hidden;
  border: 1px solid #ececea;
  border-radius: 24px;
  background: white;
}
.detail-image::before {
  content: "";
  position: absolute;
  inset: auto 0 0;
  z-index: -1;
  height: 20%;
  border-top: 1px solid #dcdcd4;
  background: #eeefea;
  transition: opacity 0.2s ease;
}
.detail-image img {
  position: absolute;
  inset: 7% 10% 20%;
