}
.cart-item-variant { color: var(--ink) !important; font-weight: 700; }
.cart-item-meta { display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 9px; color: var(--muted); font-size: 11px; }
.cart-item-controls { display: flex; align-items: end; flex-wrap: wrap; gap: 15px; margin-top: 18px; }
.cart-item-controls > div { display: grid; gap: 7px; }
.cart-item-control-label { color: var(--muted); font-size: 11px; font-weight: 700; }
.cart-remove-button { display: inline-flex; align-items: center; justify-content: center; gap: 7px; min-height: 36px; padding: 8px 10px; border: 0; border-radius: 8px; background: transparent; color: var(--muted); font-size: 11px; font-weight: 700; cursor: pointer; }
.cart-remove-button:hover { background: #fff0ed; color: #9a3535; }
.cart-remove-button:disabled { opacity: .5; cursor: not-allowed; }
.cart-item-price { display: grid; align-content: start; justify-items: end; gap: 5px; text-align: right; white-space: nowrap; }
.cart-item-price > span, .cart-item-price small { color: var(--muted); font-size: 11px; }
.cart-item-price strong { color: var(--ink); font-size: 16px; }
.cart-list-heading { display: flex; justify-content: space-between; align-items: end; gap: 18px; margin-bottom: 20px; }
.cart-list-heading .eyebrow { color: var(--lime-text); margin-bottom: 7px; }
.cart-list-heading h2 { color: var(--ink); font-size: clamp(21px, 2.1vw, 29px); letter-spacing: -.04em; }
.cart-list-heading > span { color: var(--muted); font-size: 12px; font-weight: 700; white-space: nowrap; }
.cart-page-heading { display: flex; align-items: end; justify-content: space-between; gap: 25px; margin-bottom: 38px; padding-bottom: 24px; border-bottom: 1px solid var(--line); }
.cart-page-heading .page-heading { margin-bottom: 0; }
.cart-page-heading .page-heading h1 { font-size: clamp(38px, 5vw, 64px); letter-spacing: -.055em; }
.cart-page-steps { display: flex; align-items: center; gap: 8px; color: var(--muted); }
.cart-page-steps span { display: inline-flex; align-items: center; gap: 9px; padding: 10px 13px; border-radius: 30px; font-size: 11px; font-weight: 700; white-space: nowrap; }
.cart-page-steps span[aria-current] { background: var(--lime-soft); color: var(--ink); }
.cart-page-steps strong { font-size: 10px; }
.order-flow-page .cart-item { grid-template-columns: 56px minmax(0, 1fr) auto; padding: 25px; border: 1px solid var(--line); border-radius: 16px; background: white; box-shadow: 0 9px 24px rgb(19 61 72 / .035); }
.order-flow-page .cart-item:hover, .order-flow-page .cart-item:focus-within { border-color: #c8d79c; box-shadow: 0 12px 30px rgb(19 61 72 / .07); }
.order-flow-page .cart-item + .cart-item { margin-top: 12px; }
.order-flow-page .cart-item-icon { display: grid; place-items: center; width: 56px; height: 56px; padding: 5px; overflow: hidden; border-radius: 12px; background: #edf4ef; color: var(--ink); }
.cart-item-icon img { width: 100%; height: 100%; object-fit: contain; }
.cart-item-no-image { color: var(--muted); font-size: 9px; line-height: 1.2; text-align: center; }
.order-flow-page .cart-item h3 { font-size: 17px; line-height: 1.35; }
.order-flow-page .cart-item h3:hover { color: var(--lime-text); }
.order-flow-page .cart-item-price strong { font-size: 18px; }
.order-flow-page .cart-items > .actions { margin-top: 18px; }
.cart-recommendations { margin-top: 30px; border: 1px solid var(--line); background: #f6f8f1; }
.cart-recommendations h3 { color: var(--ink); font-size: 17px; }
.summary {
  background: var(--paper);
  border-radius: 12px;
