  top: 20px;
}
.summary h2 {
  font-size: 22px;
  margin-bottom: 20px;
}
.summary .total {
  font-size: 24px;
  border-top: 1px solid var(--line);
  padding-top: 20px;
  margin-top: 20px;
}
.summary .button {
  width: 100%;
  margin-top: 22px;
}
.order-flow-page .summary { padding: 26px; border: 1px solid var(--line); border-radius: 16px; background: white; box-shadow: 0 12px 32px rgb(19 61 72 / .07); }
.cart-summary-heading { display: flex; align-items: center; gap: 12px; margin-bottom: 24px; }
.cart-summary-heading .eyebrow { margin-bottom: 5px; color: var(--lime-text); font-size: 9px; }
.cart-summary-heading h2 { margin: 0; font-size: 20px; }
.cart-summary-icon { display: grid; flex: 0 0 44px; place-items: center; width: 44px; height: 44px; border-radius: 12px; background: var(--lime-soft); color: var(--ink); }
.cart-summary-count { display: flex; justify-content: space-between; gap: 12px; padding-block: 15px; border-top: 1px solid var(--line); color: var(--muted); font-size: 13px; }
.cart-summary-count strong { color: var(--ink); }
.order-flow-page .summary .total { align-items: baseline; gap: 8px; margin-top: 0; padding-top: 17px; font-size: 16px; }
.order-flow-page .summary .total strong:last-child { font-size: 24px; white-space: nowrap; }
.cart-summary-note { display: flex; align-items: flex-start; gap: 10px; margin-top: 20px; padding: 14px; border-radius: 10px; background: var(--paper); color: var(--muted); }
.cart-summary-note svg { flex: 0 0 auto; color: var(--lime-text); }
.cart-summary-note p { font-size: 11px; line-height: 1.55; }
.order-flow-page .summary > .button { background: var(--lime); color: var(--ink); font-weight: 800; }
.order-flow-page .summary > .button:hover { background: #d9eb54; color: var(--ink); }
.cart-page .empty { margin-block: 20px; border: 1px solid var(--line); border-radius: 16px; background: var(--paper); }
/* El panel lateral comparte el lenguaje de tarjetas sin comprimir la página completa. */
.modal.modal-sheet.cart-sheet[open] { display: flex; flex-direction: column; overflow: hidden; width: min(440px, 100vw); padding: 0; border-radius: 16px 0 0 16px; background: #f8f9f5; }
.cart-sheet .modal-head { flex: 0 0 auto; margin: 0; padding: 25px 24px 20px; background: white; border-bottom: 1px solid var(--line); }
.cart-sheet .modal-head h2 { font-size: 25px; letter-spacing: -.04em; }
.cart-preview { display: flex; flex: 1; flex-direction: column; min-height: 0; }
.cart-preview-intro { flex: 0 0 auto; padding: 20px 24px 16px; }
.cart-preview-intro span { color: var(--ink); font-size: 13px; font-weight: 800; }
.cart-preview-intro p { margin-top: 5px; color: var(--muted); font-size: 12px; }
.cart-preview-items { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; display: grid; align-content: start; gap: 12px; padding: 0 24px 24px; }
.cart-preview .cart-item { grid-template-columns: 42px minmax(0, 1fr); gap: 12px; padding: 17px; border: 1px solid var(--line); border-radius: 14px; background: white; box-shadow: 0 5px 15px rgb(19 61 72 / .035); }
.cart-preview .cart-item-icon { display: grid; place-items: center; width: 42px; height: 42px; padding: 4px; overflow: hidden; border-radius: 10px; background: #edf4ef; color: var(--ink); }
.cart-preview .cart-item h3 { font-size: 14px; line-height: 1.35; }
.cart-preview .cart-item p { margin-top: 5px; }
.cart-preview .cart-item-meta { margin-top: 6px; font-size: 10px; }
.cart-preview .cart-item-meta span:first-child { display: none; }
.cart-preview .cart-item-controls { gap: 6px; margin-top: 12px; }
.cart-preview .cart-item-control-label, .cart-preview .cart-remove-button span { display: none; }
.cart-preview .quantity button { flex-basis: 31px; width: 31px; }
.cart-preview .quantity input { width: 42px; padding-block: 8px; }
.cart-preview .cart-remove-button { width: 34px; min-height: 34px; padding: 6px; }
.cart-preview .cart-item-price { grid-column: 1 / -1; display: flex; align-items: baseline; justify-content: space-between; gap: 10px; padding-top: 12px; border-top: 1px solid var(--line); text-align: left; }
.cart-preview .cart-item-price > span { font-weight: 700; }
.cart-preview .cart-item-price small { display: none; }
.cart-preview .cart-item-price strong { font-size: 15px; }
.cart-preview-foot { flex: 0 0 auto; display: grid; gap: 10px; padding: 17px 24px max(24px, env(safe-area-inset-bottom)); border-top: 1px solid var(--line); background: white; box-shadow: 0 -10px 25px rgb(19 61 72 / .05); }
.cart-preview-foot .total { align-items: baseline; gap: 8px; margin: 0 0 6px; font-size: 13px; }
.cart-preview-foot .total strong:last-child { color: var(--ink); font-size: 22px; white-space: nowrap; }
.cart-preview-foot .button { width: 100%; margin: 0; font-weight: 800; }
.cart-preview-foot .button:first-of-type { background: var(--lime); color: var(--ink); }
.cart-preview-foot .button:first-of-type:hover { background: #d9eb54; }
.cart-preview-foot .button.secondary { background: white; }
.cart-preview > .empty { margin: auto 24px; }
.orders-list {
  display: grid;
  gap: 18px;
}
.order-head {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 20px;
}
.table-wrap {
  overflow-x: auto;
  max-width: 100%;
}
table {
  border-collapse: collapse;
  width: 100%;
  font-size: 12px;
  text-align: left;
}
th,
td {
  padding: 15px 12px;
  border-bottom: 1px solid var(--line);
  vertical-align: top;
}
th {
  font-size: 10px;
  color: var(--muted);
  font-weight: 650;
  letter-spacing: 0.04em;
}
td .button {
  white-space: nowrap;
}
/* Móvil: la navegación es una franja con scroll sobre el contenido. */
.admin-shell {
  display: grid;
  gap: 24px;
}
.admin-main {
  min-width: 0;
}
.admin-route-loading { min-height: 320px; }
.admin-page dialog.modal[open],
.admin-page dialog.modal[open]::backdrop { animation: none; }
.admin-page .admin-nav a,
.admin-page .admin-nav-indicator[data-ready="true"] { transition: none; }
.admin-link-pending {
  position: absolute;
  inset: 3px auto 3px 0;
  width: 3px;
  background: var(--lime);
  opacity: 0;
  pointer-events: none;
}
