.technical-benefit-row { display: grid; grid-template-columns: minmax(130px, 1fr) minmax(0, 2fr) 38px; align-items: end; gap: 12px; margin: 14px 0; }
.technical-benefit-row input, .technical-benefit-row select { width: 100%; min-width: 0; }
.technical-sheet-actions { flex-wrap: wrap; margin-top: 20px; }
.technical-sheet-preview { padding-bottom: 20px; }
@media (max-width: 600px) {
  .technical-block-heading { flex-wrap: wrap; }
  .technical-block-heading > .field { flex-basis: 100%; }
  .technical-benefit-row { grid-template-columns: minmax(0, 1fr) 38px; }
  .technical-benefit-row .field:first-child { grid-column: 1 / -1; }
  .technical-benefits .admin-toolbar { flex-wrap: wrap; gap: 12px; }
  .technical-sheet-actions .button { width: 100%; justify-content: center; }
}
.admin-sales-table { width: 100%; min-width: 440px; }
.admin-sales-table td:not(:first-child), .admin-sales-table th:not(:first-child) { text-align: right; font-variant-numeric: tabular-nums; }
.admin-sales-table td:first-child { overflow-wrap: anywhere; }
@media (max-width: 600px) {
  .admin-sales-controls .admin-sales-periods { flex-basis: 100%; flex-wrap: wrap; }
  .admin-sales-controls .admin-sales-periods button { flex: 1 1 auto; }
  .admin-sales-date-range .field { max-width: none; }
  .favorites-toolbar { align-items: start; flex-direction: column; }
}

/* Tienda B2B: portada y catálogo según el boceto aprobado el 9/10/2026. */
.species-shortcuts {
  padding-top: 28px;
}
.species-grid {
  display: grid;
  gap: 20px;
}
.species-card,
.category-tile {
  background: white;
  border: 1px solid var(--line);
  overflow: hidden;
  box-shadow:
    0 1px 2px rgb(22 61 74 / 0.05),
    0 8px 22px rgb(22 61 74 / 0.06);
}
.species-card {
  border-radius: 18px;
}
.species-skeleton {
  min-height: 166px;
  background: var(--paper);
  box-shadow: none;
}
.species-head {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.species-head-single {
  grid-template-columns: 1fr;
}
.species-head a {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 4px;
  min-height: 112px;
  padding: 10px 8px;
  color: var(--ink-deep);
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.01em;
}
.species-main {
  background: var(--lime);
}
.species-sub {
  background: var(--lime-soft);
}
.species-art {
  flex: none;
  width: 92px;
  height: 60px;
}
.species-types {
  list-style: none;
  margin: 0;
  padding: 6px 8px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.species-types a {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 58px;
  padding: 12px 10px;
  border-radius: 12px;
  color: var(--ink-deep);
  font-size: 14px;
  font-weight: 700;
  line-height: 1.2;
}
.species-types a:hover {
  background: var(--paper);
}
.type-icon {
  flex: none;
  width: 42px;
  height: 28px;
}
.category-tiles {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding-top: 24px;
}
.category-tile {
  display: flex;
  flex-direction: column;
  border-radius: 16px;
}
.category-tile-art {
  display: grid;
  place-items: center;
  height: 78px;
  background: var(--lime);
}
.category-tile-art.is-ink {
  background: var(--ink);
}
.category-tile-art svg {
  width: 100px;
  height: 64px;
}
.category-tile-name {
  padding: 13px 8px;
  text-align: center;
  color: var(--ink-deep);
  font-size: 14px;
  font-weight: 800;
}
@media (min-width: 560px) {
  .species-head a {
    flex-direction: row;
    justify-content: flex-start;
    min-height: 92px;
    gap: 14px;
    padding: 8px 20px;
    font-size: 22px;
  }
  .species-art {
    width: 124px;
    height: 80px;
  }
  .species-types {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .species-types li + li {
    border-left: 1px solid var(--line);
  }
}
@media (min-width: 640px) {
  .category-tiles {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 16px;
  }
}
@media (min-width: 960px) {
  .species-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 28px;
  }
}
@media (min-width: 1100px) {
  .category-tiles {
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 20px;
  }
}

.brand-promos {
  display: grid;
  gap: 20px;
  padding-top: 40px;
}
.brand-promos.brand-promos-single {
  grid-template-columns: minmax(0, 1fr);
}
.brand-promo {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 270px;
  padding: 28px 32px;
  border-radius: 18px;
  overflow: hidden;
  color: var(--ink-deep);
}
.brand-promo.is-biofresh {
  background: #f6e3d4;
}
.brand-promo.is-granplus {
  background: #f6e8eb;
}
.brand-promo-copy {
  position: relative;
  z-index: 1;
  max-width: 48%;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
}
.brand-promo-logo {
  width: auto;
  height: 34px;
}
.brand-promo h2 {
  margin: 4px 0 0;
  color: var(--ink-deep);
  font-size: 26px;
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.03em;
}
.brand-promo.is-biofresh h2 span {
  color: #b4481c;
}
.brand-promo.is-granplus h2 span {
  color: #5a1f33;
}
.brand-promo p {
  margin: 0;
  color: var(--text);
  font-size: 14px;
  line-height: 1.45;
}
.brand-promo-pill {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  margin-top: 6px;
  padding: 0 22px;
  border-radius: 999px;
  background: white;
  color: var(--ink-deep);
  font-size: 14px;
  font-weight: 800;
  box-shadow: 0 2px 8px rgb(22 61 74 / 0.1);
}
.brand-promo.is-granplus .brand-promo-pill {
  background: #5a1f33;
  color: white;
}
.brand-promo-tag {
  padding: 5px 12px;
  border-radius: 4px;
  background: #5a1f33;
  color: white;
  font-size: 13px;
  font-weight: 800;
}
.brand-promo-art {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: 48%;
}
.brand-promo-packs {
  position: absolute;
  right: 16px;
  bottom: 12px;
  height: 90%;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
}
.brand-promo-packs img {
  flex: none;
  width: auto;
  height: 76%;
  filter: drop-shadow(0 10px 14px rgb(0 0 0 / 0.18));
}
.brand-promo-packs img + img {
  margin-left: -44px;
}
.brand-promo-packs img:nth-child(2) {
  position: relative;
  z-index: 1;
  height: 100%;
}
.brand-promo-circle {
  position: absolute;
  top: 50%;
  right: 26px;
  width: 196px;
  height: 196px;
  margin-top: -98px;
  border: 8px solid #5a1f33;
  border-radius: 50%;
  object-fit: cover;
}
.brand-promo-pouch {
  position: absolute;
  right: 150px;
  bottom: 16px;
  z-index: 1;
  width: auto;
  height: 76%;
  filter: drop-shadow(0 12px 16px rgb(0 0 0 / 0.25));
}
.brand-promo-wide {
  display: grid;
  border-radius: 18px;
  overflow: hidden;
  background: #232c30;
  color: var(--ink-deep);
}
.brand-promo-photo {
  display: block;
  width: 100%;
  height: 210px;
  object-fit: cover;
  object-position: 50% 30%;
}
.brand-promo-side {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 22px;
}
.brand-promo-box {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 360px;
  padding: 20px 24px;
  border-radius: 8px;
  background: white;
  box-shadow: 0 10px 24px rgb(0 0 0 / 0.18);
}
.brand-promo-box img {
  align-self: flex-start;
  width: auto;
  height: 42px;
}
.brand-promo-box strong {
  color: var(--ink-deep);
  font-size: 26px;
  line-height: 1.1;
  letter-spacing: -0.02em;
}
.brand-promo-box span {
  color: var(--text);
  font-size: 14px;
  line-height: 1.45;
}
.brand-promo-big-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 60px;
  padding: 0 34px;
  border-radius: 999px;
  background: var(--lime);
  color: var(--ink-deep);
  font-size: 18px;
  font-weight: 800;
  white-space: nowrap;
}
@media (max-width: 599px) {
  .brand-promo {
    flex-direction: column;
    align-items: stretch;
    padding: 22px;
  }
  .brand-promo-copy {
    max-width: none;
  }
  .brand-promo-art {
    position: relative;
    width: 100%;
    height: 200px;
    margin-top: 14px;
  }
  .brand-promo-circle {
    right: 8px;
    width: 160px;
    height: 160px;
    margin-top: -80px;
  }
  .brand-promo-pouch {
    right: 120px;
  }
}
@media (min-width: 900px) {
  .brand-promos {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 24px;
  }
  .brand-promo-wide {
    grid-column: 1 / -1;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-rows: minmax(0, 1fr);
    height: 260px;
  }
  .brand-promo-photo {
    height: 100%;
    min-height: 0;
  }
  .brand-promo-side {
    flex-wrap: nowrap;
    padding: 28px 44px 28px 0;
  }
  .brand-promo-box {
    margin-left: -130px;
  }
}
@media (min-width: 900px) and (max-width: 1199px) {
  .brand-promo-copy {
    max-width: 52%;
  }
  .brand-promo-packs {
    height: 75%;
  }
  .brand-promo-circle {
    right: 16px;
    width: 150px;
    height: 150px;
    margin-top: -75px;
  }
  .brand-promo-pouch {
    right: 110px;
    height: 70%;
  }
}
@media (min-width: 1100px) {
  .brand-promo h2 {
    font-size: 31px;
  }
}

.featured-tools {
  display: flex;
  align-items: center;
  gap: 8px;
}
.featured-nav {
  width: 44px;
  height: 44px;
  border: 1px solid var(--line);
}
.featured-track {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding: 2px 2px 12px;
}
.featured-track::-webkit-scrollbar {
  display: none;
}
.featured-track .product-card {
  flex: none;
  scroll-snap-align: start;
}

/* Tarjeta de ancho fijo y altura adaptable; la foto conserva su caja. */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, 276px);
  justify-content: start;
  gap: 20px;
}
.product-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 276px;
  min-height: 480px;
  height: auto;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: white;
  overflow: hidden;
}
.featured-track .product-card {
  width: 240px;
}
.product-card-media {
  position: relative;
  flex: 1;
  min-height: 260px;
}
.featured-track .product-card-media {
  min-height: 240px;
}
.product-image {
  position: absolute;
  inset: 0;
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 14px;
  border-radius: 12px;
  background: #f7f8f5;
  overflow: hidden;
}
.product-image img {
  display: block;
  width: auto;
  height: auto;
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  mix-blend-mode: multiply;
}
.product-card .tag {
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 1;
  padding: 4px 8px;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: white;
  font-size: 10px;
}
.product-meta {
  min-height: 1.3em;
  margin-top: 4px;
  color: var(--lime-text);
  font-size: 12.5px;
  font-weight: 700;
}
.product-card h3 {
  display: -webkit-box;
  height: 2.7em;
  margin: 0;
  overflow: hidden;
  color: var(--ink-deep);
  font-size: 16px;
  font-weight: 700;
  line-height: 1.35;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.product-price {
  flex: none;
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: hidden;
  font-size: 13px;
}
.product-variants { position: absolute; z-index: 2; bottom: 6px; left: 6px; right: 6px; display: flex; align-items: center; gap: 6px; min-height: 36px; overflow-x: auto; padding: 3px 1px; scrollbar-width: thin; }
.product-variant-pill { flex: none; max-width: 100%; padding: 5px 10px; border: 1px solid var(--line); border-radius: 999px; background: white; color: var(--ink); font-size: 12px; line-height: 1.4; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; box-shadow: 0 2px 4px rgb(0 0 0 / .06); }
.product-variant-pill[aria-pressed="true"] { border-color: var(--ink); box-shadow: 0 0 0 1px var(--ink); }
.product-card-buy { margin-top: 0; }
.product-card-actions { display: flex; gap: 8px; align-items: center; border: 0; padding: 0; min-width: 0; }
.product-card-actions .quantity { flex: 0 0 104px; }
.product-card-actions .quantity input { width: 40px; }
.product-card-actions .quantity button { width: 30px; flex-basis: 30px; }
.product-card-actions > .button { flex: 1; min-height: 40px; padding-inline: 8px; justify-content: center; }
.product-card-note { margin-top: 6px; font-size: 11px; line-height: 1.45; color: var(--muted); }
.product-price-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 2px 8px;
  padding: 8px 12px;
  color: var(--text);
}
.product-price-row strong {
  color: var(--ink-deep);
  font-size: 16px;
}
.product-price-locked {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--ink);
  font-size: 12px;
}
.product-cta {
  justify-content: center;
  white-space: nowrap;
  width: 100%;
  min-height: 44px;
  margin-top: auto;
}
@media (max-width: 600px) {
  .product-grid {
    grid-template-columns: repeat(auto-fill, 156px);
    justify-content: center;
    gap: 16px 12px;
  }
  .product-card,
  .featured-track .product-card {
    width: 156px;
    min-height: 440px;
    height: auto;
    padding: 10px;
  }
  .product-card-media,
  .featured-track .product-card-media {
    min-height: 190px;
  }
  .product-image {
    padding: 10px;
  }
  .product-card h3 {
    font-size: 14px;
  }
  .product-card-actions { flex-wrap: wrap; }
  .product-card-actions .quantity { flex-basis: 100%; justify-content: center; }
  .product-card-actions > .button { flex-basis: 100%; }
  .product-variant-pill { padding: 5px 8px; font-size: 11px; }
  .product-price-row {
    padding: 8px 10px;
  }
  .product-cta {
    padding-inline: 6px;
    font-size: 12px;
  }
  .product-price-locked {
    font-size: 11px;
  }
  .product-card .tag {
    top: 8px;
    left: 8px;
    font-size: 8px;
  }
}

/* Catálogo: cabecera con promoción, tipos de producto y filtros plegables. */
.catalog-head {
  display: grid;
  gap: 18px;
  align-items: center;
}
.catalog-head .page-heading {
  margin-bottom: 0;
}
.catalog-promo {
  display: flex;
  align-items: center;
  gap: 24px;
  min-height: 170px;
  padding: 22px 24px;
  border-radius: 18px;
  background: var(--lime-soft);
  color: var(--ink-deep);
  overflow: hidden;
}
.catalog-promo-copy {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
}
.catalog-promo-copy img {
  width: auto;
  height: 26px;
}
.catalog-promo h2 {
  margin: 6px 0 0;
  font-size: 22px;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
}
.catalog-promo p {
  margin: 0 0 8px;
  color: var(--text);
  font-size: 14px;
}
.catalog-promo-packs {
  display: none;
  flex: none;
  align-items: flex-end;
  height: 150px;
}
.catalog-promo-packs img {
  width: auto;
  height: 88%;
  filter: drop-shadow(0 8px 12px rgb(0 0 0 / 0.15));
}
.catalog-promo-packs img + img {
  margin-left: -24px;
}
.catalog-promo-packs img:nth-child(2) {
  position: relative;
  z-index: 1;
  height: 100%;
}
.catalog-types {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding: 18px 2px 6px;
  scrollbar-width: none;
}
.catalog-type {
  flex: none;
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 56px;
  padding: 8px 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: white;
  color: var(--ink-deep);
  font: inherit;
  font-size: 14px;
  font-weight: 700;
  line-height: 1.2;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.2s ease;
}
.catalog-type:hover {
  border-color: var(--lime);
}
.catalog-type[aria-pressed="true"] {
  border-color: var(--ink);
  background: var(--lime-soft);
  box-shadow: inset 0 0 0 1px var(--ink);
}
.catalog-type .type-icon {
  width: 40px;
  height: 26px;
}
.catalog-layout {
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  align-items: start;
  gap: 32px;
  margin-top: 22px;
}
.catalog-results {
  min-width: 0;
}
.catalog-results > .product-grid {
  column-gap: 32px;
}
@media (min-width: 1024px) {
  .catalog-results > .product-grid {
    column-gap: 64px;
  }
}
@media (max-width: 600px) {
  .catalog-results > .product-grid {
    column-gap: clamp(12px, calc(100vw - 344px), 20px);
  }
}
.filters-panel {
  margin-top: 14px;
  padding: 4px 18px 16px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: white;
}
.filter-switch {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 52px;
  border-bottom: 1px solid var(--line);
  color: var(--ink-deep);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.filter-switch input {
  appearance: none;
  position: relative;
  flex: none;
  width: 40px;
  height: 24px;
  margin: 0;
  border-radius: 999px;
  background: #b8bfb6;
  cursor: pointer;
  transition: background-color 0.2s ease;
}
.filter-switch input::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: white;
  transition: translate 0.2s ease;
}
.filter-switch input:checked {
  background: var(--ink);
}
.filter-switch input:checked::after {
  translate: 16px 0;
}
.filter-switch input:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}
.filter-section {
  border-bottom: 1px solid var(--line);
}
.filter-section > summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 52px;
  color: var(--ink-deep);
  cursor: pointer;
  list-style: none;
}
.filter-section > summary::-webkit-details-marker {
  display: none;
}
.filter-section > summary h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0;
}
.filter-section > summary svg {
  flex: none;
  transition: rotate 0.2s ease;
}
.filter-section[open] > summary svg {
  rotate: 180deg;
}
.filter-section > :not(summary) {
  margin-bottom: 14px;
}
.filter-section .filter-option {
  font-size: 13.5px;
}
@media (min-width: 700px) {
  .catalog-promo {
    padding: 22px 36px;
  }
  .catalog-promo-packs {
    display: flex;
  }
  .catalog-promo h2 {
    font-size: 28px;
  }
}
@media (min-width: 1024px) {
  .catalog-head {
    grid-template-columns: 280px minmax(0, 1fr);
    gap: 32px;
  }
  .catalog-types {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    margin-left: 312px;
  }
}
/* Por debajo de 1024 px los filtros se abren en el panel modal existente. */
@media (max-width: 1023px) {
  .catalog-layout {
    display: block;
  }
  .filters {
    display: none;
  }
  .filter-trigger {
    display: inline-flex;
  }
}
@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .species-art,
  .category-tile,
  .brand-promo,
  .brand-promo-wide {
    transition:
      translate var(--dur-base, 0.25s) var(--ease-out, ease),
      box-shadow var(--dur-base, 0.25s) var(--ease-out, ease);
  }
  .species-head a:hover .species-art {
    translate: 0 -3px;
  }
  .category-tile:hover,
  .brand-promo:hover,
  .brand-promo-wide:hover {
    translate: 0 -2px;
    box-shadow: 0 14px 30px rgb(22 61 74 / 0.12);
  }
}
.security-form { max-width: 460px; }
.security-agent, .security-key { overflow-wrap: anywhere; }
.recovery-codes { border: 1px solid var(--border); border-radius: 6px; padding: 16px; margin: 16px 0; }
.recovery-codes code { font-size: 13px; overflow-wrap: anywhere; }
